import numpy as np

def clean(df):
    df = df.drop_duplicates().reset_index(drop=True)
    df.loc[df['flipper_length_mm'] < 170, 'flipper_length_mm'] = np.nan
    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '', regex=False).astype(float)
    df['sex'] = df['sex'].str.lower()
    return df

def answer(df):
    return df.groupby('species')['flipper_length_mm'].mean().to_dict()
